using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using BeamScheduleFormatter;
class LongProjectTitleTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static string Compact(string value){return new string(value.Where(c=>!char.IsWhiteSpace(c)).ToArray());}
 static void Reject(Action action,string why){bool failed=false;try{action();}catch{failed=true;}Check(failed,why);}
 static void Main(){var register=typeof(Encoding).GetMethod("RegisterProvider");bool has1252=true;try{System.Text.Encoding.GetEncoding(1252);}catch{has1252=false;}if(register!=null&&!has1252){var type=System.Reflection.Assembly.Load("System.Text.Encoding.CodePages").GetType("System.Text.CodePagesEncodingProvider");register.Invoke(null,new[]{type.GetProperty("Instance").GetValue(null,null)});}string old=ProjectInfoStore.DirectoryPath,dir=Path.Combine(Path.GetTempPath(),"DTCE-title-tests-"+Guid.NewGuid().ToString("N"));ProjectInfoStore.DirectoryPath=dir;try{
 string title="CONVERGENCE AND SPECIAL SUPPORT PROGRAM (CSSP) - BASIC INFRASTRUCTURE PROGRAM (BIP) -\r\nMULTI-PURPOSE BUILDINGS / FACILITIES TO SUPPORT SOCIAL SERVICES -\r\nCONSTRUCTION (COMPLETION) OF MULTI-PURPOSE BUILDING",location="BARANGAY MABANGUC, APARRI, CAGAYAN (18.288626°N 121.645228°E)";
 ProjectInfoStore.Save(title,location,"Engineering Office","Office Address");var p=ProjectInfoStore.Read();Check(p.Name==title.Replace("\r\n","\n"),"Long multiline screenshot title round trips without truncation");Check(p.Location==location,"Coordinate location preserved");Check(p.Office=="Engineering Office","Office remains compatible");
 File.WriteAllText(Path.Combine(Path.GetTempPath(),"LongProjectTitle-Sample.html"),new EngineeringReport{Title="Quantity take-off report",Project=p.Name,Location=p.Location,Office=p.Office}.Html());EngineeringQuantityPdf.Write(Path.Combine(Path.GetTempPath(),"LongProjectTitle-Layout.pdf"),new EngineeringReport{Title="Quantity take-off report",Project=p.Name,Location=p.Location,Office=p.Office});var lines=ProjectReportHeader.Lines(p,475);Check(Compact(string.Join("",lines))==Compact(p.NameLine+p.LocationLine),"Complete project metadata preserved in wrapped preview header");Check(lines.Count>=4,"Pasted new lines remain visible");
 string maximum=new string('&',2000);ProjectInfoStore.Save(maximum,new string('W',500),"Engineering Office","Office Address");p=ProjectInfoStore.Read();Check(p.Name==maximum&&p.Location.Length==500,"Maximum fields round trip through escaped XML");Reject(()=>ProjectInfoStore.Save(new string('X',2001),""),"Oversized title rejected explicitly rather than truncated");Check(ProjectInfoStore.Read().Name==maximum,"Invalid save preserves prior project");
 var report=new EngineeringReport{Title="Long project title test",Project=p.Name,Location=p.Location,Office=p.Office};report.Section("Quantities").Table(new[]{"Description","Quantity"},new[]{new[]{"Column concrete","0.54 m3"}});var plan=EngineeringQuantityPdf.Plan(report);var text=plan.DrawingPages.SelectMany(x=>x).Where(x=>x.Kind=="text").ToList();string painted=Compact(string.Join("",text.Select(x=>x.Text)));Check(painted.Contains(Compact("Project: "+maximum)),"PDF plan includes entire 2,000-character title");Check(painted.Contains(Compact("Location: "+p.Location)),"PDF plan includes entire long location");Check(text.All(x=>x.Size>=7&&x.Y>=25&&x.Y<=806),"A4 layout preserves minimum font size and page bounds");Check(text.Any(x=>x.Text.Contains("Column concrete")),"Body follows full metadata");string html=report.Html();Check(html.Contains("white-space:pre-wrap")&&html.Contains("overflow-wrap:anywhere"),"HTML preserves manual line breaks and wraps long tokens");Check(html.Contains(EngineeringReport.Escape(maximum)),"HTML retains escaped full title");
 int rows=ProjectReportHeader.PreviewRows(p);Check(rows<54&&rows>0,"Legacy preview reserves space for long header");Check(ProjectReportHeader.PreviewBodyTop(p)+rows*12<=795,"Legacy body remains above footer");string body=string.Join("\n",Enumerable.Range(0,120).Select(i=>"ROW "+i));var pages=EstimatePdf.Pages(body);Check(pages.All(x=>x.Count<=rows)&&pages.Sum(x=>x.Count)==120,"Legacy pagination preserves all rows after header expands");
 ProjectInfoStore.Save(string.Join("\n",Enumerable.Repeat("LINE",300)),"Location");Check(ProjectReportHeader.UseFlowingPreview(ProjectInfoStore.Read()),"Many explicit lines select flowing report pagination");ProjectInfoStore.Save("Legacy short title","Legacy location");Check(ProjectReportHeader.PreviewRows(ProjectInfoStore.Read())==54,"Short-title pagination remains unchanged");Console.WriteLine("PASS: "+checks+" project-title persistence, wrapping and pagination checks");
 }finally{ProjectInfoStore.DirectoryPath=old;if(Directory.Exists(dir))Directory.Delete(dir,true);}}
}
